/** Locale chunks generated at build time (LOC-6): `vite.config.ts` → `voidLocaleChunks`
 *  serves each id from `bakedLocale()`, so the module is a plain key → text map with
 *  the fallback language already merged in. */
declare module 'virtual:void-locale/*' {
  const messages: Record<string, string>;
  export default messages;
}
